"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[66952],{52485:e=>{e.exports=JSON.parse('{"tag":{"label":"comparison","permalink":"/tags/comparison","allTagsPath":"/tags","count":11,"items":[{"id":"reports/date-range","title":"Date Range","description":"Control the time period for all reports with preset ranges, custom dates, and comparison periods.","permalink":"/reports/date-range"},{"id":"faq/ga4-vs-sealmetrics","title":"GA4 vs Sealmetrics \u2014 Complete Comparison","description":"Detailed comparison of Google Analytics 4 and Sealmetrics covering data accuracy, privacy compliance, features, and pricing.","permalink":"/faq/ga4-vs-sealmetrics"},{"id":"troubleshooting/lower-numbers-than-other-tools","title":"Numbers Lower Than Another Tool","description":"Why Sealmetrics can legitimately report fewer (or more) visits than GA4 or another tool: entrances vs sessions, bot filtering at ingest, and no sampling.","permalink":"/troubleshooting/lower-numbers-than-other-tools"},{"id":"api/comparison","title":"Period Comparison","description":"Compare analytics between time periods with the compare parameter \u2014 previous period or year-over-year deltas on any stats endpoint","permalink":"/api/comparison"},{"id":"compare/index","title":"Sealmetrics compared with other analytics tools","description":"How Sealmetrics compares with GA4, Matomo, Plausible, Fathom, Piwik PRO and Simple Analytics on identifiers, IP handling, data residency, consent and script size.","permalink":"/compare/"},{"id":"compare/fathom","title":"Sealmetrics vs Fathom: EU Isolation vs EU-only storage","description":"Fathom hashes IP and user agent daily and stores anonymised data in the US after EU processing. Sealmetrics never hashes the IP and keeps all data in Dublin.","permalink":"/compare/fathom"},{"id":"compare/google-analytics-4","title":"Sealmetrics vs Google Analytics 4: consent-based vs consentless measurement","description":"GA4 needs cookies and consent, so it loses 15\u201360% of EU visitors. Sealmetrics measures every hit without cookies, IP storage or a banner, hosted in Dublin.","permalink":"/compare/google-analytics-4"},{"id":"compare/matomo","title":"Sealmetrics vs Matomo: self-hosted open source vs managed consentless cloud","description":"Matomo is GPL-licensed and self-hostable, but its cookieless mode hashes the visitor\'s IP. Sealmetrics never uses the IP and stores everything in Dublin.","permalink":"/compare/matomo"},{"id":"compare/piwik-pro","title":"Sealmetrics vs Piwik PRO: enterprise suite with consent manager vs consentless by design","description":"Piwik PRO pairs analytics with a consent manager and an anonymous mode hashed from the IP. Sealmetrics needs no consent layer, no IP and stores only in Dublin.","permalink":"/compare/piwik-pro"},{"id":"compare/plausible","title":"Sealmetrics vs Plausible: two cookieless tools, one hashes the IP","description":"Plausible identifies visitors with a daily hash of IP and user agent; Sealmetrics never derives an identifier from the IP. Both cookieless, both EU-hosted.","permalink":"/compare/plausible"},{"id":"compare/simple-analytics","title":"Sealmetrics vs Simple Analytics: the closest architecture, different depth","description":"Both skip cookies, IPs and consent banners and derive country from the timezone. Simple Analytics keeps it minimal; Sealmetrics adds attribution, e-commerce and AI.","permalink":"/compare/simple-analytics"}],"unlisted":false}}')}}]);